import React, { useEffect, useRef, useState } from "react";
import "./ContentSection.css";

export const ContentSection = ({ scrollToContact }) => {
  const [activeSection, setActiveSection] = useState(0);
  const sectionRef = useRef(null);
  const cardRefs = useRef([]);
  const markerRefs = useRef([]);

  // Set up scroll markers to control section changes
  useEffect(() => {
    // Create marker elements to trigger section changes
    const createMarkers = () => {
      const container = sectionRef.current;
      if (!container) return;

      // Clear existing markers
      markerRefs.current.forEach(marker => marker && marker.remove());
      markerRefs.current = [];

      // Create a marker for each section
      const numSections = cardRefs.current.length;
      const sectionHeight = window.innerHeight;

      for (let i = 0; i < numSections; i++) {
        const marker = document.createElement('div');
        marker.className = 'scroll-marker';
        marker.dataset.index = i;
        marker.style.top = `${i * sectionHeight}px`;
        container.appendChild(marker);
        markerRefs.current.push(marker);
      }
    };

    createMarkers();

    // Recreate markers on window resize
    window.addEventListener('resize', createMarkers);
    return () => window.removeEventListener('resize', createMarkers);
  }, []);

  // Set up intersection observer for markers
  useEffect(() => {
    const options = {
      root: null,
      rootMargin: '-50% 0px -50% 0px', // Consider the center of the viewport
      threshold: 0
    };

    const handleIntersect = (entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          const index = parseInt(entry.target.dataset.index, 10);
          setActiveSection(index);
        }
      });
    };

    const observer = new IntersectionObserver(handleIntersect, options);

    // Observe all markers
    markerRefs.current.forEach(marker => {
      if (marker) observer.observe(marker);
    });

    return () => {
      if (markerRefs.current) {
        markerRefs.current.forEach(marker => {
          if (marker) observer.unobserve(marker);
        });
      }
    };
  }, [markerRefs.current.length]);

  // Set active class on the current section
  useEffect(() => {
    cardRefs.current.forEach((card, index) => {
      if (card) {
        if (index === activeSection) {
          card.classList.add('active');
        } else {
          card.classList.remove('active');
        }
      }
    });
  }, [activeSection]);

  // Handle indicator click to scroll to section
  const scrollToSection = (index) => {
    // Calculate position to scroll to
    const sectionHeight = window.innerHeight;
    const yPosition = index * sectionHeight;

    // Scroll to the position
    window.scrollTo({
      top: sectionRef.current.offsetTop + yPosition,
      behavior: 'smooth'
    });
  };

  return (
    <div className="content-section" id="services-section" ref={sectionRef}>
      <div className="split-layout">
        {/* Left Side - Content changes based on scroll */}
        <div className="left-side">
          <div className="feature-title">CUSTOM AGENTIC DEPLOYMENT</div>
          <div className="feature-description">
            {activeSection === 0 && "Streamline Your Workflows"}
            {activeSection === 1 && "Reduce Operational Turnaround"}
            {activeSection === 2 && "Unleash Team Potential"}
            {activeSection === 3 && "Expert Support & Guidance"}
            {activeSection === 4 && "Data-Driven Insights"}
            {activeSection === 5 && "Seamless Integration"}
          </div>
          <div className="feature-details">
            {activeSection === 0 && "Turn your business challenges into opportunities with AI agents that your teams can actually use."}
            {activeSection === 1 && "Scale operations efficiently while maintaining headcount with AI-powered process optimization."}
            {activeSection === 2 && "Free your team from routine tasks and allow them to focus on innovation and problem-solving."}
            {activeSection === 3 && "Receive dedicated support from our experts, ensuring your success every step of the way."}
            {activeSection === 4 && "Make informed decisions with powerful analytics and reporting capabilities."}
            {activeSection === 5 && "Our solutions integrate effortlessly with your existing systems for minimal disruption."}
          </div>
        </div>

        {/* Right Side - Cards positioned absolutely so they occupy the same space */}
        <div className="right-side">
          <div 
            className="feature-card highlight" 
            ref={el => cardRefs.current[0] = el} 
            data-index="0"
          >
            <div className="feature-card-title">Streamline intricate workflows from start to finish</div>
            <div className="feature-card-text">
              Handle multi-step processes autonomously with AI Agents, from reading emails to updating
              systems and making decisions.
            </div>
          </div>

          <div 
            className="feature-card" 
            ref={el => cardRefs.current[1] = el} 
            data-index="1"
          >
            <div className="feature-card-title">Reduce operational turnaround times without sacrificing quality</div>
            <div className="feature-card-text">
              Scale operations while maintaining headcount. Our AI agents are able to increase the
              efficiency and effectiveness of your teams as you grow.
            </div>
          </div>

          <div 
            className="feature-card" 
            ref={el => cardRefs.current[2] = el} 
            data-index="2"
          >
            <div className="feature-card-title">Unleash your team's potential</div>
            <div className="feature-card-text">
              Provide solutions that your teams will actually use. Let AI handle routine tasks while your
              team focuses on strategy, innovation, and complex problem-solving.
            </div>
          </div>

          <div 
            className="feature-card highlight" 
            ref={el => cardRefs.current[3] = el} 
            data-index="3"
          >
            <div className="feature-card-title">Expert Support and Guidance</div>
            <div className="feature-card-text">
              Receive dedicated support from our team of experts, committed to assisting you at every step
              and ensuring your success with our AI solutions.
            </div>
          </div>

          {/* Add a few more cards to ensure sufficient scroll space */}
          <div 
            className="feature-card" 
            ref={el => cardRefs.current[4] = el} 
            data-index="4"
          >
            <div className="feature-card-title">Data-Driven Insights</div>
            <div className="feature-card-text">
              Leverage powerful analytics and reporting capabilities to gain valuable insights into your
              operations and make informed strategic decisions.
            </div>
          </div>

          <div 
            className="feature-card" 
            ref={el => cardRefs.current[5] = el} 
            data-index="5"
          >
            <div className="feature-card-title">Seamless Integration</div>
            <div className="feature-card-text">
              Our AI solutions integrate effortlessly with your existing systems and workflows, ensuring
              a smooth transition and minimal disruption to your operations.
            </div>
          </div>
        </div>

        {/* Navigation indicators */}
        <div className="section-indicators">
          {[0, 1, 2, 3, 4, 5].map(index => (
            <div 
              key={index}
              className={`indicator ${activeSection === index ? 'active' : ''}`}
              onClick={() => scrollToSection(index)}
            />
          ))}
        </div>
      </div>
    </div>
  );
};
